1	import type { LineChartOptions, ChartResult } from "../types.js";
2	import { resolveTheme } from "../themes/index.js";
3	import { colorize, padStart, stripAnsi, visibleLength, ansi } from "../ansi.js";
4	import { formatNumber } from "../utils.js";
5	import { createLineChartModel, lineModelToPlain, lineModelToSvg, type LineSeriesModel } from "./line-model.js";
6	import { BrailleCanvas, plotLineOnBrailleCanvas } from "../renderers/braille.js";
7	import { frameTop, frameBottom, frameRow, frameRule } from "../renderers/panel.js";
8	
9	function terminalWidth(explicit?: number): number {
10	  if (explicit) return explicit;
11	  const cols = typeof process !== "undefined" ? process.stdout?.columns : undefined;
12	  return Math.max(60, Math.min(cols || 76, 100));
13	}
14	
15	/** The 3 dot-columns around the primary series max get the single accent —
16	 *  the rest of the curve stays on the tone ramp (LOCKED: accent spent once). */
17	function primaryPeakCap(series: LineSeriesModel | undefined, dotCols: number): Set<number> {
18	  const cap = new Set<number>();
19	  if (!series || series.values.length < 2) return cap;
20	  let maxIdx = 0;
21	  let maxVal = series.values[0] ?? Number.NEGATIVE_INFINITY;
22	  series.values.forEach((v, i) => {
23	    if (v > maxVal) {
24	      maxVal = v;
25	      maxIdx = i;
26	    }
27	  });
28	  const peakDotX = Math.round((maxIdx / (series.values.length - 1)) * (dotCols - 1));
29	  cap.add(peakDotX - 1);
30	  cap.add(peakDotX);
31	  cap.add(peakDotX + 1);
32	  return cap;
33	}
34	
35	/** Texture-coded strokes, matching the reference's legend dash language: the
36	 *  primary is SOLID (step 1), the first extra series is DASHED (step 2 — cell
37	 *  on / cell off), and every later series is DOTTED (step 3). Keeps crossing
38	 *  curves distinguishable in plain monochrome. */
39	function lineTextureStep(seriesIndex: number): number {
40	  if (seriesIndex === 0) return 1;
41	  return seriesIndex === 1 ? 2 : 3;
42	}
43	
44	/** Texture is a MONOCHROME fallback only — in colour mode every series draws
45	 *  as a solid line exactly like the reference (the dash language lives on the
46	 *  gridlines, not the series). */
47	function seriesStrokeStep(seriesIndex: number, noColor: boolean): number {
48	  return noColor ? lineTextureStep(seriesIndex) : 1;
49	}
50	
51	/** Legend style hint text — in colour mode every legend is a solid `──glyph──`
52	 *  dash pair (identity via colour, like the reference); in monochrome each
53	 *  series keeps its own dash character so the texture survives without colour. */
54	const DASH_CHARS = ["──", "╌╌", "··", "─╌"];
55	
56	function dashCharsFor(seriesIndex: number, noColor: boolean): string {
57	  if (!noColor) return DASH_CHARS[0]!;
58	  if (seriesIndex === 0) return DASH_CHARS[0]!;
59	  return DASH_CHARS[((seriesIndex - 1) % (DASH_CHARS.length - 1)) + 1]!;
60	}
61	
62	/** Every series drops its glyph marker (○ + × □) at every 2nd data point, so
63	 *  crossing curves are identifiable by shape even in monochrome — matching the
64	 *  SVG (index % 2 === 0). Markers beat lower-priority braille but the accent
65	 *  cap on the primary peak outranks them. */
66	function markerCells(
67	  series: LineSeriesModel[],
68	  colors: string[],
69	  plotCols: number,
70	  plotRows: number,
71	  yMin: number,
72	  yMax: number,
73	  noColor: boolean
74	): Map<number, string> {
75	  const markers = new Map<number, string>();
76	  if (series.length === 0) return markers;
77	  const dotCols = plotCols * 2;
78	  const dotRows = plotRows * 4;
79	  series.forEach((s, si) => {
80	    if (s.values.length < 2) return;
81	    for (let i = 0; i < s.values.length; i += 2) {
82	      const dotX = Math.round((i / (s.values.length - 1)) * (dotCols - 1));
83	      const cell = Math.floor(dotX / 2);
84	      const v = s.values[i] ?? 0;
85	      const norm = yMax === yMin ? 0.5 : (v - yMin) / (yMax - yMin);
86	      const dotY = dotRows - 1 - Math.round(norm * (dotRows - 1));
87	      const row = Math.floor(dotY / 4);
88	      const key = row * plotCols + cell;
89	      if (!markers.has(key)) markers.set(key, colorize(s.marker, colors[si]!, noColor));
90	    }
91	  });
92	  return markers;
93	}
94	
95	/** Merge per-series braille rows into one row; empty cells are SPACES — never
96	 *  blank-braille (U+2800), which renders as faint dots. Priority per cell:
97	 *  primary accent cap > glyph marker > series line > grid guide. */
98	function mergeLineCells(
99	  lines: string[],
100	  markers: Map<number, string>,
101	  row: number,
102	  colors: string[],
103	  accent: string,
104	  cap: Set<number>,
105	  noColor: boolean
106	): string {
107	  if (lines.length === 0) return "";
108	  const len = Math.max(...lines.map((l) => l.length));
109	  let out = "";
110	  for (let i = 0; i < len; i++) {
111	    let ch = " ";
112	    let si = -1;
113	    for (let k = 0; k < lines.length; k++) {
114	      const c = lines[k]?.[i] ?? " ";
115	      if (c !== " ") {
116	        ch = c;
117	        si = k;
118	        break;
119	      }
120	    }
121	    if (si === -1) {
122	      out += " ";
123	      continue;
124	    }
125	    const inCap = si === 0 && (cap.has(i * 2) || cap.has(i * 2 + 1));
126	    if (inCap) {
127	      out += colorize(ch, accent, noColor);
128	      continue;
129	    }
130	    const marker = markers.get(row * len + i);
131	    if (marker) {
132	      out += marker;
133	      continue;
134	    }
135	    out += colorize(ch, colors[si]!, noColor);
136	  }
137	  return out;
138	}
139	
140	/** Renders a chitra-standard TUI panel carrying the LOCKED S09 design
141	 *  language: dashed frame, eyebrow row, `│` y-guide, braille line on the tone
142	 *  ramp with the accent spent once on the peak, `+` x-tick marks, and footer
143	 *  stats per series. In colour mode every series draws solid like the
144	 *  reference; in monochrome strokes are texture-coded (primary solid, extras
145	 *  dashed/dotted) so crossing curves stay separable. */
146	export function line(opts: LineChartOptions): ChartResult {
147	  const theme = resolveTheme(opts.theme);
148	  const noColor = opts.noColor ?? false;
149	  const width = terminalWidth(opts.width);
150	  const height = opts.height ?? 14;
151	  const renderer = opts.renderer ?? "braille";
152	  const showAxes = opts.showAxes !== false;
153	
154	  const model = createLineChartModel(opts);
155	  const innerWidth = width - 4; // minus "│ " ... " │"
156	  const acc = theme.accent!;
157	  const tones = theme.tones!;
158	  // Same "one hue + tone ramp" language as the LOCKED pie/donut/area charts.
159	  // A lone line keeps the LOCKED grey body with the accent spent once on its
160	  // peak. With several series the primary becomes the accent hero (like the
161	  // pie's largest slice) and the extras recede onto the shared grey ramp —
162	  // identity among the greys comes from the glyph markers (`* ○ + × □`), never
163	  // from separate bright hues.
164	  const multiSeries = model.series.length > 1;
165	  const toneOrder = [tones[2], tones[0], tones[3] ?? tones[1], tones[1]].filter(Boolean) as string[];
166	  const seriesColors = model.series.map((_, i) =>
167	    i === 0 && multiSeries ? acc : toneOrder[i % toneOrder.length]!
168	  );
169	
170	  const yAxisW =
171	    Math.max(
172	      formatNumber(Math.round(model.yMax)).length,
173	      formatNumber(Math.round(model.yMin)).length
174	    ) + 1;
175	  const plotCols = Math.max(8, innerWidth - yAxisW - 2);
176	  const plotRows = Math.max(3, height - 2);
177	
178	  const yStep = Math.max(1, Math.floor(plotRows / 5));
179	  /** Gridline rows (every yStep) get a dotted guide that never hides a curve —
180	   *  series cells and markers outrank it, and it skips the top/base rows. Rendered
181	   *  dim (one dot every 2nd column, like the reference's `9 9` dash) so it reads
182	   *  as a faint backdrop, never a competing stroke. */
183	  const showGrid = opts.grid ?? false;
184	  function isGridRow(row: number): boolean {
185	    return showGrid && row > 0 && row < plotRows - 1 && row % yStep === 0;
186	  }
187	
188	  function dashedGrid(cols: number): string {
189	    let out = "";
190	    for (let col = 0; col < cols; col++) out += col % 2 === 0 ? "·" : " ";
191	    return out;
192	  }
193	
194	  function plotRowLabel(row: number): string {
195	    if (!showAxes) return "";
196	    const yVal = model.yMax - (row / Math.max(1, plotRows - 1)) * (model.yMax - model.yMin);
197	    return (row % yStep === 0 || row === plotRows - 1)
198	      ? padStart(formatNumber(Math.round(yVal)), yAxisW - 1)
199	      : " ".repeat(yAxisW - 1);
200	  }
201	
202	  const smooth = opts.smooth ?? true;
203	  function renderBrailleRows(): string[] {
204	    const canvases = model.series.map(() => new BrailleCanvas(plotCols, plotRows));
205	    model.series.forEach((s, si) => {
206	      if (s.values.length >= 2) {
207	        plotLineOnBrailleCanvas(canvases[si]!, s.values, model.yMin, model.yMax, smooth);
208	        canvases[si]!.thin(seriesStrokeStep(si, noColor));
209	      }
210	    });
211	    const cap = primaryPeakCap(model.series[0], plotCols * 2);
212	    const markers = markerCells(model.series, seriesColors, plotCols, plotRows, model.yMin, model.yMax, noColor);
213	    const gridColor = [...seriesColors, ansi.dim + (theme.grid ?? theme.axis)];
214	    const rows: string[] = [];
215	    for (let row = 0; row < plotRows; row++) {
216	      const lines = canvases.map((c) => c.toLines(" ")[row] ?? "");
217	      lines.push(isGridRow(row) ? dashedGrid(plotCols) : " ".repeat(plotCols));
218	      const cells = mergeLineCells(lines, markers, row, gridColor, acc, cap, noColor);
219	      const guide = row === 0 ? "+" : "│";
220	      const prefix = showAxes ? colorize(plotRowLabel(row) + guide, theme.axis, noColor) : "";
221	      rows.push(prefix + cells);
222	    }
223	    return rows;
224	  }
225	
226	  function renderBlockRows(): string[] {
227	    const grid = Array.from({ length: plotRows }, () => Array<string>(plotCols).fill(""));
228	    const cellCap = new Set<number>();
229	    const primary = model.series[0];
230	
231	    function setCell(col: number, yRow: number, ch: string, color: string): void {
232	      if (yRow < 0 || yRow >= plotRows || col < 0 || col >= plotCols) return;
233	      if (grid[yRow]![col]) return;
234	      grid[yRow]![col] = colorize(ch, color, noColor);
235	    }
236	
237	    if (primary && primary.values.length >= 2) {
238	      let maxIdx = 0;
239	      let maxVal = primary.values[0] ?? Number.NEGATIVE_INFINITY;
240	      primary.values.forEach((v, i) => {
241	        if (v > maxVal) {
242	          maxVal = v;
243	          maxIdx = i;
244	        }
245	      });
246	      const peakCell = Math.round((maxIdx / (primary.values.length - 1)) * (plotCols - 1));
247	      cellCap.add(peakCell - 1);
248	      cellCap.add(peakCell);
249	      cellCap.add(peakCell + 1);
250	    }
251	
252	    const yRowFor = (v: number): number => {
253	      const yNorm = model.yMax === model.yMin ? 0.5 : (v - model.yMin) / (model.yMax - model.yMin);
254	      return Math.round((1 - yNorm) * (plotRows - 1));
255	    };
256	
257	    /** Glyph-chain pass: every series drops its marker at every 2nd data point
258	     *  (i += 2, matching the reference), and that's ALL the block renderer
259	     *  draws — no `●` filler. The curve reads by following the marker chain,
260	     *  so the plot stays airy and traceable with several crossing series. */
261	    model.series.forEach((s, si) => {
262	      if (s.values.length < 2) return;
263	      const color = seriesColors[si]!;
264	      for (let i = 0; i < s.values.length; i += 2) {
265	        const col = Math.round((i / (s.values.length - 1)) * (plotCols - 1));
266	        const isCap = si === 0 && cellCap.has(col);
267	        setCell(col, yRowFor(s.values[i] ?? 0), s.marker, isCap ? acc : color);
268	      }
269	    });
270	
271	    /** The ascii renderer is the one exception: it needs a connecting line too,
272	     *  because bare markers don't read in pure ASCII. So it paints an
273	     *  interpolated `●`/slope line under its markers. The block renderer never
274	     *  reaches this pass. */
275	    if (renderer === "ascii") {
276	      model.series.forEach((s, si) => {
277	        if (s.values.length < 2) return;
278	        const color = seriesColors[si]!;
279	        const step = noColor ? 2 + Math.min(si, 2) : 2;
280	        for (let col = 0; col < plotCols; col++) {
281	          if (col % step !== 0) continue;
282	          const exactX = (col / Math.max(1, plotCols - 1)) * (s.values.length - 1);
283	          const idxL = Math.floor(exactX);
284	          const idxR = Math.min(s.values.length - 1, Math.ceil(exactX));
285	          const frac = exactX - idxL;
286	          const val = idxL === idxR ? s.values[idxL]! : s.values[idxL]! * (1 - frac) + s.values[idxR]! * frac;
287	          const yRow = yRowFor(val);
288	
289	          let ch: string;
290	          if (col > 0) {
291	            const isExactPoint = frac < 0.1 || frac > 0.9;
292	            if (!isExactPoint) {
293	              const prevX = ((col - 1) / Math.max(1, plotCols - 1)) * (s.values.length - 1);
294	              const prevVal = s.values[Math.floor(prevX)]!;
295	              ch = val > prevVal + 1e-9 ? "/" : val < prevVal - 1e-9 ? "\\" : "-";
296	            } else {
297	              ch = s.marker;
298	            }
299	          } else {
300	            ch = s.marker;
301	          }
302	          const isCap = si === 0 && cellCap.has(col);
303	          setCell(col, yRow, ch, isCap ? acc : color);
304	        }
305	      });
306	    }
307	
308	    for (let row = 0; row < plotRows; row++) {
309	      if (!isGridRow(row)) continue;
310	      for (let col = 0; col < plotCols; col++) {
311	        if (col % 2 === 0 && !grid[row]![col]) grid[row]![col] = colorize("·", ansi.dim + (theme.grid ?? theme.axis), noColor);
312	      }
313	    }
314	
315	    const rows: string[] = [];
316	    for (let row = 0; row < plotRows; row++) {
317	      const guide = row === 0 ? "+" : "│";
318	      const prefix = showAxes ? colorize(plotRowLabel(row) + guide, theme.axis, noColor) : "";
319	      rows.push(prefix + grid[row]!.join(""));
320	    }
321	    return rows;
322	  }
323	
324	  function renderXAxisLabels(): string[] {
325	    if (!showAxes || model.labels.length === 0) return [];
326	    const n = model.labels.length;
327	    const slotW = Math.max(1, Math.floor(plotCols / n));
328	    const labelChars = Array<string>(plotCols).fill(" ");
329	    model.labels.forEach((label, i) => {
330	      const truncated = label.slice(0, slotW);
331	      const slotStart = Math.round((i * plotCols) / n);
332	      const slotEnd = Math.min(plotCols, Math.round(((i + 1) * plotCols) / n));
333	      let startCol = slotStart + Math.floor((slotEnd - slotStart - truncated.length) / 2);
334	      if (startCol < 0) startCol = 0;
335	      for (let j = 0; j < truncated.length && startCol + j < plotCols; j++) {
336	        labelChars[startCol + j] = truncated[j]!;
337	      }
338	    });
339	    return [" ".repeat(yAxisW) + colorize(labelChars.join(""), theme.label, noColor)];
340	  }
341	
342	  /** The reference puts a `+` on the x-axis at every tick. In the terminal that
343	   *  becomes a dedicated axis-colour tick row between the plot and the label
344	   *  row, with a `+` aligned to each label slot. */
345	  function renderXTickMarks(): string[] {
346	    if (!showAxes || model.labels.length === 0) return [];
347	    const n = model.labels.length;
348	    const cells = Array<string>(plotCols).fill(" ");
349	    model.labels.forEach((_, i) => {
350	      const slotStart = Math.round((i * plotCols) / n);
351	      const slotEnd = Math.min(plotCols, Math.round(((i + 1) * plotCols) / n));
352	      const mid = slotStart + Math.floor((slotEnd - slotStart) / 2);
353	      cells[mid] = "+";
354	    });
355	    return [" ".repeat(yAxisW) + colorize(cells.join(""), theme.axis, noColor)];
356	  }
357	
358	  function renderLegend(): string[] {
359	    if (!model.showLegend || model.series.length === 0) return [];
360	    const items = model.series.map((s, i) =>
361	      colorize(`${dashCharsFor(i, noColor)}${s.marker}${dashCharsFor(i, noColor)} ${s.name}`, seriesColors[i]!, noColor)
362	    );
363	    return wrapItems(items, innerWidth);
364	  }
365	
366	  /** Compact block spark bar (`▁▂▃▄▅▆▇█`) — the terminal echo of the reference's
367	   *  per-series sparkline in the summary panel. */
368	  const SPARK_CHARS = "▁▂▃▄▅▆▇█";
369	
370	  function sparkline(values: number[], color: string, width = 14): string {
371	    if (values.length === 0) return "";
372	    const lo = Math.min(...values);
373	    const hi = Math.max(...values);
374	    const range = hi - lo || 1;
375	    let out = "";
376	    for (let i = 0; i < width; i++) {
377	      const idx = Math.min(values.length - 1, Math.floor(((i + 0.5) / width) * values.length));
378	      const t = ((values[idx] ?? lo) - lo) / range;
379	      out += SPARK_CHARS[Math.min(7, Math.round(t * 7))]!;
380	    }
381	    return colorize(out, color, noColor);
382	  }
383	
384	  function renderSummary(): string[] {
385	    if (model.series.length === 0) return [];
386	    const nameW = Math.max(...model.series.map((s) => visibleLength(s.name) + 2));
387	    const rows = model.series.map((s, si) => {
388	      const stats = s.stats;
389	      const name = colorize(`${s.marker} ${s.name}`.padEnd(nameW), seriesColors[si]!, noColor);
390	      const maxPart = si === 0
391	        ? colorize(`max ${formatNumber(stats.max)}`, acc, noColor)
392	        : `max ${formatNumber(stats.max)}`;
393	      const left = `${name} · min ${formatNumber(stats.min)} · ${maxPart} · avg ${formatNumber(stats.avg)} · last ${formatNumber(stats.last)}`;
394	      const room = innerWidth - visibleLength(left) - 3;
395	      const sparkW = room < 4 ? 0 : Math.min(14, room);
396	      const spark = sparkline(s.values, seriesColors[si]!, sparkW);
397	      const pad = Math.max(0, innerWidth - visibleLength(left) - visibleLength(spark) - 1);
398	      return left + " ".repeat(pad) + spark;
399	    });
400	    return wrapItems(rows, innerWidth);
401	  }
402	
403	  function buildLines(): string[] {
404	    const lines: string[] = [];
405	    const eyebrow = (opts.eyebrow ?? "TREND").toUpperCase();
406	    lines.push(frameTop(width, opts.title ?? "LINE", opts.timestamp, theme.axis, theme.title, noColor, true));
407	    lines.push(frameRule(width, theme.axis, noColor));
408	    lines.push(frameRow(width, colorize(eyebrow, theme.label, noColor), theme.axis, noColor));
409	    for (const item of renderLegend()) lines.push(frameRow(width, item, theme.axis, noColor));
410	
411	    const plotRowsOut = renderer === "braille" ? renderBrailleRows() : renderBlockRows();
412	    for (const row of plotRowsOut) lines.push(frameRow(width, row, theme.axis, noColor));
413	    for (const row of renderXTickMarks()) lines.push(frameRow(width, row, theme.axis, noColor));
414	    for (const row of renderXAxisLabels()) lines.push(frameRow(width, row, theme.axis, noColor));
415	
416	    if (model.showSummary) {
417	      lines.push(frameRule(width, theme.axis, noColor));
418	      for (const row of renderSummary()) lines.push(frameRow(width, row, theme.axis, noColor));
419	    }
420	
421	    if (opts.status) {
422	      lines.push(frameRule(width, theme.axis, noColor));
423	      lines.push(frameRow(width, colorize(`Status: ${opts.status}`, theme.title, noColor), theme.axis, noColor));
424	    }
425	    lines.push(frameBottom(width, theme.axis, noColor, true));
426	    return lines;
427	  }
428	
429	  const output = buildLines().join("\n");
430	
431	  return {
432	    render() { process.stdout.write(output + "\n"); },
433	    toString() { return output; },
434	    toPlain() { return stripAnsi(output); },
435	    toMarkdown() { return "```\n" + stripAnsi(output) + "\n```"; },
436	    toJSON() {
437	      return {
438	        type: "line",
439	        data: opts.data,
440	        labels: opts.labels,
441	        title: opts.title,
442	        plain: stripAnsi(output),
443	        model: lineModelToPlain(model),
444	      };
445	    },
446	    toSVG() { return lineModelToSvg(model); },
447	  };
448	}
449	
450	function wrapItems(items: string[], maxWidth: number): string[] {
451	  const rows: string[] = [];
452	  let current = "";
453	  for (const item of items) {
454	    const candidate = current ? current + "  " + item : item;
455	    if (visibleLength(candidate) > maxWidth && current) {
456	      rows.push(current);
457	      current = item;
458	    } else {
459	      current = candidate;
460	    }
461	  }
462	  if (current) rows.push(current);
463	  return rows;
464	}
