1	export function clamp(value: number, min: number, max: number): number {
2	  return Math.max(min, Math.min(max, value));
3	}
4	
5	export function normalize(
6	  value: number,
7	  min: number,
8	  max: number,
9	  targetMin = 0,
10	  targetMax = 1
11	): number {
12	  if (max === min) return targetMin;
13	  return targetMin + ((value - min) / (max - min)) * (targetMax - targetMin);
14	}
15	
16	export function range(start: number, end: number, step = 1): number[] {
17	  const result: number[] = [];
18	  for (let i = start; i < end; i += step) result.push(i);
19	  return result;
20	}
21	
22	export function minMax(data: number[]): { min: number; max: number } {
23	  let min = Infinity;
24	  let max = -Infinity;
25	  for (const v of data) {
26	    if (v < min) min = v;
27	    if (v > max) max = v;
28	  }
29	  return { min, max };
30	}
31	
32	export function minMaxFlat(data: number[][]): { min: number; max: number } {
33	  return minMax(data.flat());
34	}
35	
36	export function niceTicks(min: number, max: number, maxTicks = 5): { min: number; max: number; step: number; ticks: number[] } {
37	  if (min === max) return { min, max, step: 1, ticks: [min] };
38	  const range = max - min;
39	  const rawStep = range / (maxTicks - 1);
40	  const mag = Math.pow(10, Math.floor(Math.log10(rawStep)));
41	  const norm = rawStep / mag;
42	  
43	  let step: number;
44	  if (norm < 1.5) step = 1 * mag;
45	  else if (norm < 3) step = 2 * mag;
46	  else if (norm < 7.5) step = 5 * mag;
47	  else step = 10 * mag;
48	
49	  // STRICT bounds: Do not force 0 if min is > 0. Just step down once.
50	  let niceMin = Math.floor(min / step) * step;
51	  let niceMax = Math.ceil(max / step) * step;
52	  
53	  const ticks: number[] = [];
54	  for (let t = niceMin; t <= niceMax + 1e-9; t += step) {
